from dataclasses import dataclass
from typing import Protocol


@dataclass(frozen=True)
class Linea:
    precio: float
    cantidad: int


def calcular_total(lineas: list[Linea], vip: bool) -> float:
    """Regla de negocio pura: sin E/S, trivial de probar."""
    total = sum(linea.precio * linea.cantidad for linea in lineas)
    return round(total * 0.9 if vip else total, 2)


class Almacen(Protocol):          # el «puerto»: lo que el servicio necesita
    def guardar(self, pedido_id: int, total: float) -> None: ...


class AlmacenMemoria:             # un adaptador (aquí, un fake para pruebas)
    def __init__(self) -> None:
        self.datos: dict[int, float] = {}

    def guardar(self, pedido_id: int, total: float) -> None:
        self.datos[pedido_id] = total


class ServicioPedidos:
    def __init__(self, almacen: Almacen) -> None:
        self._almacen = almacen   # inyección por constructor

    def procesar(self, pedido_id: int, lineas: list[Linea], vip: bool) -> float:
        total = calcular_total(lineas, vip)
        self._almacen.guardar(pedido_id, total)
        return total


almacen = AlmacenMemoria()
servicio = ServicioPedidos(almacen)
print(servicio.procesar(1, [Linea(10.0, 2), Linea(5.5, 1)], vip=True))
print(almacen.datos)

