from typing import Callable

Descuento = Callable[[float], float]


def sin_descuento(subtotal: float) -> float:
    return 0.0


def diez_por_ciento(subtotal: float) -> float:
    return subtotal * 0.10


def cinco_desde_50(subtotal: float) -> float:
    return 5.0 if subtotal >= 50 else 0.0


PROMOCIONES: dict[str, Descuento] = {
    "ninguna": sin_descuento,
    "diez": diez_por_ciento,
    "cinco": cinco_desde_50,
}


def precio_final(subtotal: float, promo: Descuento = sin_descuento) -> float:
    return round(subtotal - promo(subtotal), 2)


for nombre, promo in PROMOCIONES.items():
    print(f"{nombre:>8}: {precio_final(60.0, promo)}")

# La mejor promoción para el cliente, sin un solo if:
mejor = max(PROMOCIONES.values(), key=lambda p: p(60.0))
print("mejor:", mejor.__name__)

import csv
import io
import json

_EXPORTADORES: dict[str, type] = {}


def registrar(formato: str):
    def decorador(cls):
        _EXPORTADORES[formato] = cls
        return cls
    return decorador


@registrar("json")
class ExportadorJSON:
    def exportar(self, filas: list[dict]) -> str:
        return json.dumps(filas, ensure_ascii=False)


@registrar("csv")
class ExportadorCSV:
    def exportar(self, filas: list[dict]) -> str:
        salida = io.StringIO()
        escritor = csv.DictWriter(salida, fieldnames=list(filas[0]), lineterminator="\n")
        escritor.writeheader()
        escritor.writerows(filas)
        return salida.getvalue()


def crear_exportador(formato: str):
    try:
        return _EXPORTADORES[formato.lower()]()
    except KeyError:
        opciones = ", ".join(sorted(_EXPORTADORES))
        raise ValueError(f"Formato desconocido {formato!r}. Opciones: {opciones}") from None


