from typing import Protocol


class Notificador(Protocol):
    def notificar(self, destino: str, texto: str) -> None: ...


class ErrorNotificacion(Exception):
    """Excepción de NUESTRO dominio."""


# --- Biblioteca de terceros (no podemos cambiarla) ---
class ProveedorSMS:
    def send(self, to: str, body: str, priority: int = 1) -> dict:
        if not to.startswith("+"):
            raise RuntimeError("E_FORMAT")
        return {"status": "queued", "to": to}


# --- Nuestro adaptador ---
class NotificadorSMS:
    def __init__(self, proveedor: ProveedorSMS) -> None:
        self._proveedor = proveedor

    def notificar(self, destino: str, texto: str) -> None:
        try:
            self._proveedor.send(to=destino, body=texto[:160])
        except RuntimeError as e:
            raise ErrorNotificacion(f"No se pudo enviar a {destino}") from e


def avisar_envio(notificador: Notificador, telefono: str) -> str:
    try:
        notificador.notificar(telefono, "Tu pedido ha salido")
        return "avisado"
    except ErrorNotificacion as e:
        return f"fallo: {e}"


