import sqlite3
from dataclasses import dataclass


@dataclass(frozen=True)
class Producto:
    id: int
    sku: str
    nombre: str


class SkuDuplicado(Exception):
    pass


class RepositorioProductos:
    def __init__(self, con: sqlite3.Connection) -> None:
        self._con = con
        with con:
            con.execute("CREATE TABLE IF NOT EXISTS productos ("
                        "id INTEGER PRIMARY KEY, sku TEXT NOT NULL UNIQUE, nombre TEXT NOT NULL)")

    def agregar(self, sku: str, nombre: str) -> Producto:
        try:
            with self._con:
                cur = self._con.execute(
                    "INSERT INTO productos (sku, nombre) VALUES (?, ?)", (sku, nombre))
        except sqlite3.IntegrityError as e:
            raise SkuDuplicado(sku) from e           # traducción al lenguaje del dominio
        return Producto(cur.lastrowid, sku, nombre)

    def por_sku(self, sku: str) -> Producto | None:
        fila = self._con.execute(
            "SELECT id, sku, nombre FROM productos WHERE sku = ?", (sku,)).fetchone()
        return Producto(*fila) if fila else None


repo = RepositorioProductos(sqlite3.connect(":memory:"))
print(repo.agregar("CAF-01", "Café en grano"))
try:
    repo.agregar("CAF-01", "Otro café")
except SkuDuplicado as e:
    print("Duplicado:", e, "| causa:", type(e.__cause__).__name__)
print(repo.por_sku("CAF-01"), repo.por_sku("NOPE"))

