VERDADEROS = {"1", "true", "yes", "on", "si"}
FALSOS = {"0", "false", "no", "off"}
NIVELES = {"DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"}


def _leer_bool(nombre, texto):
    valor = texto.strip().lower()
    if valor in VERDADEROS:
        return True
    if valor in FALSOS:
        return False
    raise ValueError(f"{nombre} debe ser booleano (1/0, true/false, on/off...): {texto!r}")


def leer_config(entorno):
    """Devuelve {'host', 'puerto', 'debug', 'nivel_log'} a partir de un mapping."""
    host = entorno.get("APP_HOST", "127.0.0.1").strip()
    if not host:
        raise ValueError("APP_HOST no puede estar vacío")

    texto_puerto = entorno.get("APP_PORT", "8000")
    try:
        puerto = int(texto_puerto)
    except ValueError:
        raise ValueError(f"APP_PORT debe ser un entero: {texto_puerto!r}") from None
    if not 1 <= puerto <= 65535:
        raise ValueError(f"APP_PORT fuera de rango (1-65535): {puerto}")

    debug = _leer_bool("APP_DEBUG", entorno.get("APP_DEBUG", "false"))

    nivel = entorno.get("APP_LOG_LEVEL", "INFO").strip().upper()
    if nivel not in NIVELES:
        raise ValueError(f"APP_LOG_LEVEL no válido: {nivel!r}")

    return {"host": host, "puerto": puerto, "debug": debug, "nivel_log": nivel}

