import secrets
import string

SIMBOLOS = "!@#$%&*-_?"
ALFABETO = string.ascii_letters + string.digits + SIMBOLOS


def _es_robusta(clave):
    return (any(c.islower() for c in clave)
            and any(c.isupper() for c in clave)
            and any(c.isdigit() for c in clave)
            and any(c in SIMBOLOS for c in clave))


def generar_contrasena(longitud=16):
    if isinstance(longitud, bool) or not isinstance(longitud, int):
        raise TypeError("longitud debe ser un entero")
    if longitud < 8:
        raise ValueError("La longitud mínima es 8")
    while True:
        clave = "".join(secrets.choice(ALFABETO) for _ in range(longitud))
        if _es_robusta(clave):
            return clave

