import tomllib
from dataclasses import dataclass

SECCIONES = {"app", "servidor", "base_datos"}


@dataclass(frozen=True)
class Config:
    nombre: str
    debug: bool = False
    puerto: int = 8000
    hosts: tuple[str, ...] = ("localhost",)
    ruta_bd: str = "app.db"


def _comprobar_tipo(clave, valor, tipo):
    # bool es subclase de int: hay que excluirlo a mano cuando se espera un int
    if not isinstance(valor, tipo) or (tipo is int and isinstance(valor, bool)):
        raise ValueError(f"{clave} debe ser de tipo {tipo.__name__}, no {type(valor).__name__}")
    return valor


def cargar_config(texto):
    try:
        datos = tomllib.loads(texto)
    except tomllib.TOMLDecodeError as e:
        raise ValueError(f"TOML inválido en la línea {e.lineno}: {e.msg}") from e

    desconocidas = set(datos) - SECCIONES
    if desconocidas:
        raise ValueError(f"Secciones desconocidas: {', '.join(sorted(desconocidas))}")

    app = _comprobar_tipo("[app]", datos.get("app", {}), dict)
    servidor = _comprobar_tipo("[servidor]", datos.get("servidor", {}), dict)
    base_datos = _comprobar_tipo("[base_datos]", datos.get("base_datos", {}), dict)

    if "nombre" not in app:
        raise ValueError("Falta app.nombre")
    nombre = _comprobar_tipo("app.nombre", app["nombre"], str).strip()
    if not nombre:
        raise ValueError("app.nombre no puede estar vacío")

    debug = _comprobar_tipo("app.debug", app.get("debug", False), bool)

    puerto = _comprobar_tipo("servidor.puerto", servidor.get("puerto", 8000), int)
    if not 1 <= puerto <= 65535:
        raise ValueError(f"servidor.puerto fuera de rango (1-65535): {puerto}")

    hosts = _comprobar_tipo("servidor.hosts", servidor.get("hosts", ["localhost"]), list)
    if not hosts or not all(isinstance(h, str) and h.strip() for h in hosts):
        raise ValueError("servidor.hosts debe ser una lista no vacía de cadenas no vacías")

    ruta_bd = _comprobar_tipo("base_datos.ruta", base_datos.get("ruta", "app.db"), str)

    return Config(nombre=nombre, debug=debug, puerto=puerto,
                  hosts=tuple(hosts), ruta_bd=ruta_bd)

