class BusEventos:
    def __init__(self):
        self._manejadores = {}     # evento -> lista de callables, en orden
        self.errores = []

    def suscribir(self, evento, manejador):
        if not callable(manejador):
            raise TypeError("El manejador debe ser invocable")
        lista = self._manejadores.setdefault(evento, [])
        if manejador not in lista:
            lista.append(manejador)

        def cancelar():
            if manejador in lista:
                lista.remove(manejador)

        return cancelar

    def publicar(self, evento, **datos):
        exitos = 0
        for manejador in list(self._manejadores.get(evento, [])):   # copia
            try:
                manejador(**datos)
            except Exception as e:
                self.errores.append((evento, e))
            else:
                exitos += 1
        return exitos

