import hashlib
import hmac


def _firma(mensaje, clave):
    return hmac.new(clave, mensaje.encode("utf-8"), hashlib.sha256).hexdigest()


def firmar(mensaje, clave):
    if not clave:
        raise ValueError("La clave no puede estar vacía")
    return f"{mensaje}.{_firma(mensaje, clave)}"


def verificar(token, clave):
    mensaje, separador, firma = token.rpartition(".")
    if not separador:
        return None
    try:
        recibida = firma.encode("ascii")          # una firma válida siempre es ASCII
    except UnicodeEncodeError:
        return None
    esperada = _firma(mensaje, clave).encode("ascii")
    if hmac.compare_digest(esperada, recibida):
        return mensaje
    return None

