import base64
import hashlib
import hmac
import secrets

ALGORITMO = "pbkdf2_sha256"


def pbkdf2_sha256(password, sal, iteraciones):
    """PBKDF2-HMAC-SHA256 con 32 bytes de salida (RFC 8018). No la modifiques.

    Usa hashlib.pbkdf2_hmac (OpenSSL) si existe; en el navegador (Pyodide,
    sin OpenSSL) recurre a una implementación equivalente con hmac.
    """
    if hasattr(hashlib, "pbkdf2_hmac"):
        return hashlib.pbkdf2_hmac("sha256", password, sal, iteraciones)
    prf = hmac.new(password, digestmod="sha256")
    bloque = prf.copy()
    bloque.update(sal + (1).to_bytes(4, "big"))
    u = bloque.digest()
    acumulado = int.from_bytes(u, "big")
    for _ in range(iteraciones - 1):
        siguiente = prf.copy()
        siguiente.update(u)
        u = siguiente.digest()
        acumulado ^= int.from_bytes(u, "big")
    return acumulado.to_bytes(32, "big")


def hashear_password(password, *, iteraciones=600_000, sal=None):
    if not isinstance(password, str) or not password:
        raise ValueError("La contraseña debe ser una cadena no vacía")
    if iteraciones < 1000:
        raise ValueError("Se necesitan al menos 1000 iteraciones")
    if sal is None:
        sal = secrets.token_bytes(16)
    derivada = pbkdf2_sha256(password.encode("utf-8"), sal, iteraciones)
    return "$".join([
        ALGORITMO,
        str(iteraciones),
        base64.b64encode(sal).decode("ascii"),
        base64.b64encode(derivada).decode("ascii"),
    ])


def _separar(almacenado):
    """Devuelve (algoritmo, iteraciones, sal, hash) o lanza ValueError."""
    partes = almacenado.split("$")
    if len(partes) != 4:
        raise ValueError("Formato de hash no válido")
    algoritmo, texto_iter, sal_b64, hash_b64 = partes
    iteraciones = int(texto_iter)                        # ValueError si no es un número
    sal = base64.b64decode(sal_b64, validate=True)       # binascii.Error es un ValueError
    esperado = base64.b64decode(hash_b64, validate=True)
    if iteraciones < 1 or not sal or not esperado:
        raise ValueError("Formato de hash no válido")
    return algoritmo, iteraciones, sal, esperado


def verificar_password(password, almacenado):
    try:
        algoritmo, iteraciones, sal, esperado = _separar(almacenado)
    except ValueError:
        return False
    if algoritmo != ALGORITMO:
        return False
    calculado = pbkdf2_sha256(password.encode("utf-8"), sal, iteraciones)
    return hmac.compare_digest(calculado, esperado)


def necesita_rehash(almacenado, iteraciones_actuales):
    algoritmo, iteraciones, _, _ = _separar(almacenado)
    return algoritmo != ALGORITMO or iteraciones < iteraciones_actuales

