import re
import sqlite3
from dataclasses import dataclass

PATRON_EMAIL = re.compile(r"[^@\s]+@[^@\s]+\.[^@\s]+")


@dataclass(frozen=True)
class Contacto:
    id: int
    nombre: str
    email: str


class EmailDuplicado(Exception):
    """El email ya está registrado."""


class RepositorioMemoria:
    def __init__(self):
        self._por_id = {}
        self._siguiente_id = 1

    def agregar(self, nombre, email):
        if self.buscar_por_email(email) is not None:
            raise EmailDuplicado(email)
        contacto = Contacto(self._siguiente_id, nombre, email)
        self._por_id[contacto.id] = contacto
        self._siguiente_id += 1
        return contacto

    def obtener(self, id_):
        return self._por_id.get(id_)

    def buscar_por_email(self, email):
        return next((c for c in self._por_id.values() if c.email == email), None)

    def listar(self):
        return sorted(self._por_id.values(), key=lambda c: (c.nombre, c.id))


class RepositorioSQLite:
    def __init__(self, conexion):
        self._con = conexion
        with self._con:
            self._con.execute(
                "CREATE TABLE IF NOT EXISTS contactos ("
                " id INTEGER PRIMARY KEY,"
                " nombre TEXT NOT NULL,"
                " email TEXT NOT NULL UNIQUE)"
            )

    def agregar(self, nombre, email):
        try:
            with self._con:                               # COMMIT o ROLLBACK
                cursor = self._con.execute(
                    "INSERT INTO contactos (nombre, email) VALUES (?, ?)", (nombre, email)
                )
        except sqlite3.IntegrityError as e:
            raise EmailDuplicado(email) from e
        return Contacto(cursor.lastrowid, nombre, email)

    def _uno(self, sql, parametros):
        fila = self._con.execute(sql, parametros).fetchone()
        return Contacto(*fila) if fila else None

    def obtener(self, id_):
        return self._uno("SELECT id, nombre, email FROM contactos WHERE id = ?", (id_,))

    def buscar_por_email(self, email):
        return self._uno("SELECT id, nombre, email FROM contactos WHERE email = ?", (email,))

    def listar(self):
        filas = self._con.execute("SELECT id, nombre, email FROM contactos ORDER BY nombre, id")
        return [Contacto(*fila) for fila in filas]


class ServicioContactos:
    def __init__(self, repositorio):
        self._repo = repositorio

    def registrar(self, nombre, email):
        nombre = nombre.strip()
        email = email.strip().lower()
        if not nombre:
            raise ValueError("El nombre es obligatorio")
        if not PATRON_EMAIL.fullmatch(email):
            raise ValueError(f"Email no válido: {email!r}")
        return self._repo.agregar(nombre, email)


def crear_repositorio(url):
    if url == "memoria://":
        return RepositorioMemoria()
    ruta = url.removeprefix("sqlite://")
    if url.startswith("sqlite://") and ruta:
        return RepositorioSQLite(sqlite3.connect(ruta))
    raise ValueError(f"URL de repositorio no soportada: {url!r}")

