import json
import logging
import logging.config
from datetime import datetime, timezone

ESTANDAR = set(vars(logging.makeLogRecord({}))) | {"message", "asctime"}


class FormateadorJSON(logging.Formatter):
    def format(self, record):
        instante = datetime.fromtimestamp(record.created, timezone.utc)
        evento = {
            "ts": instante.isoformat(timespec="milliseconds"),
            "nivel": record.levelname,
            "logger": record.name,
            "mensaje": record.getMessage(),
        }
        for clave, valor in vars(record).items():
            if clave not in ESTANDAR and clave not in evento:
                evento[clave] = valor
        if record.exc_info:
            evento["excepcion"] = self.formatException(record.exc_info)
        return json.dumps(evento, ensure_ascii=False, default=str)


def configurar_logging(destino, nivel="INFO"):
    logging.config.dictConfig({
        "version": 1,
        "disable_existing_loggers": False,
        "formatters": {"json": {"()": FormateadorJSON}},
        "handlers": {
            "principal": {
                "class": "logging.StreamHandler",
                "stream": destino,
                "formatter": "json",
            },
        },
        "loggers": {
            "app": {"level": nivel.upper(), "handlers": ["principal"], "propagate": False},
        },
    })

