import json
import logging
import time
import urllib.error
import urllib.parse
import urllib.request

logger = logging.getLogger("clienteapi")

REINTENTABLES = {429, 500, 502, 503, 504}


class ErrorAPI(Exception):
    def __init__(self, mensaje, estado=None):
        super().__init__(mensaje)
        self.estado = estado


def _mensaje_de_error(error):
    """Campo "error" del cuerpo JSON de un HTTPError o, si no hay, 'HTTP <código>'."""
    try:
        cuerpo = json.loads(error.read())
    except ValueError:                      # cuerpo vacío o que no es JSON
        cuerpo = None
    if isinstance(cuerpo, dict) and isinstance(cuerpo.get("error"), str):
        return cuerpo["error"]
    return f"HTTP {error.code}"


def _retry_after(error):
    valor = error.headers.get("Retry-After") if error.headers is not None else None
    if valor is not None and str(valor).strip().isdigit():
        return float(valor)
    return None


class ClienteAPI:
    def __init__(self, base_url, *, token=None, abrir=urllib.request.urlopen,
                 dormir=time.sleep, reintentos=3, espera_base=0.5, timeout=10.0):
        self._base = base_url.rstrip("/")
        self._token = token
        self._abrir = abrir
        self._dormir = dormir
        self._reintentos = reintentos
        self._espera_base = espera_base
        self._timeout = timeout

    # --- Construcción de la petición (sin E/S) ---
    def _peticion(self, metodo, ruta, params=None, datos=None):
        url = f"{self._base}/{ruta.lstrip('/')}"
        if params:
            url += "?" + urllib.parse.urlencode(params, doseq=True)
        cabeceras = {"Accept": "application/json"}
        if self._token:
            cabeceras["Authorization"] = f"Bearer {self._token}"
        cuerpo = None
        if datos is not None:
            cuerpo = json.dumps(datos).encode("utf-8")
            cabeceras["Content-Type"] = "application/json"
        return urllib.request.Request(url, data=cuerpo, headers=cabeceras, method=metodo)

    # --- Un intento: enviar y decodificar ---
    def _enviar(self, peticion):
        with self._abrir(peticion, timeout=self._timeout) as respuesta:
            estado = getattr(respuesta, "status", 200)
            cuerpo = respuesta.read()
        if estado == 204 or not cuerpo:
            return None
        try:
            return json.loads(cuerpo)
        except ValueError as e:
            raise ErrorAPI(f"Respuesta no JSON de {peticion.full_url}", estado) from e

    def get(self, ruta, **params):
        peticion = self._peticion("GET", ruta, params=params)
        intento = 0
        while True:
            try:
                return self._enviar(peticion)
            except urllib.error.HTTPError as e:          # antes que URLError: es su subclase
                if e.code not in REINTENTABLES:
                    raise ErrorAPI(_mensaje_de_error(e), e.code) from e
                ultimo, estado, espera = e, e.code, _retry_after(e)
            except (urllib.error.URLError, TimeoutError) as e:
                ultimo, estado, espera = e, None, None
            intento += 1
            if intento > self._reintentos:
                raise ErrorAPI(f"Sin respuesta válida tras {intento} intentos: {ultimo}", estado) from ultimo
            if espera is None:
                espera = self._espera_base * 2 ** (intento - 1)
            logger.warning("Reintento %d/%d de %s en %.1f s (%s)",
                           intento, self._reintentos, peticion.full_url, espera, ultimo)
            self._dormir(espera)

    def post(self, ruta, datos):
        peticion = self._peticion("POST", ruta, datos=datos)
        try:
            return self._enviar(peticion)
        except urllib.error.HTTPError as e:
            raise ErrorAPI(_mensaje_de_error(e), e.code) from e
        except (urllib.error.URLError, TimeoutError) as e:
            raise ErrorAPI(f"Error de red: {e}") from e

