class RespuestaFalsa:
    """Imita lo que devuelve urlopen: gestor de contexto con status, headers y read()."""
    def __init__(self, cuerpo=b"", status=200, headers=None):
        if not isinstance(cuerpo, bytes):
            cuerpo = json.dumps(cuerpo).encode("utf-8")
        self._cuerpo = cuerpo
        self.status = status
        self.headers = headers or {}

    def read(self):
        return self._cuerpo

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        return False


def error_http(codigo, cuerpo=b"", headers=None):
    if not isinstance(cuerpo, bytes):
        cuerpo = json.dumps(cuerpo).encode("utf-8")
    return urllib.error.HTTPError("https://api.example.com", codigo, "error",
                                  headers or {}, io.BytesIO(cuerpo))


class ServidorFalso:
    """abrir falso: devuelve (o lanza) los resultados del guion en orden y anota las peticiones."""
    def __init__(self, *guion):
        self.guion = list(guion)
        self.peticiones = []
        self.timeouts = []

    def __call__(self, peticion, timeout=None):
        self.peticiones.append(peticion)
        self.timeouts.append(timeout)
        if not self.guion:
            raise AssertionError("Se hizo una petición de más: el guion del servidor falso ya se agotó")
        resultado = self.guion.pop(0)
        if isinstance(resultado, BaseException):
            raise resultado
        return resultado


def cliente(servidor, esperas=None, **kwargs):
    destino = esperas if esperas is not None else []
    return ClienteAPI("https://api.example.com/v1", abrir=servidor, dormir=destino.append, **kwargs)


def _espera_error(funcion, *args):
    try:
        funcion(*args)
    except ErrorAPI as e:
